use verus::*;

// Helper function: check if a char is an uppercase letter
fn is_uppercase(c: char) -> bool {
    c >= 'A' && c <= 'Z'
}

// Helper function: check if a char is a lowercase letter
fn is_lowercase(c: char) -> bool {
    c >= 'a' && c <= 'z'
}

// Helper function: check if char is a vowel (one of the specified vowels)
fn is_vowel(c: char) -> bool {
    c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' ||
    c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U'
}

// Helper function: vowel replacement without changing case.
// returns the mapped character with the SAME case as input vowel c.
fn vowel_replace(c: char) -> char {
    match c {
        'a' => 'c',
        'e' => 'g',
        'i' => 'k',
        'o' => 'q',
        'u' => 'w',
        'A' => 'C',
        'E' => 'G',
        'I' => 'K',
        'O' => 'Q',
        'U' => 'W',
        _ => c // should not happen if input is vowel
    }
}

// Helper function: swap case of a letter character.
// uppercase to lowercase, lowercase to uppercase.
// assumes input is a letter ('A'-'Z' or 'a'-'z').
fn swap_case(c: char) -> char {
    if is_uppercase(c) {
        // uppercase to lowercase
        ((c as u8) + 32) as char
    } else if is_lowercase(c) {
        // lowercase to uppercase
        ((c as u8) - 32) as char
    } else {
        // not a letter, return unchanged (should not happen in this function)
        c
    }
}

